"""BroadTrend strategy specification, matched portfolio evidence and inspectors."""
import base64,gzip,html,json
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import research_broadtrend_blend as s
from build_trend_sleeve_portfolio_report import table,pct,num,eq,chart
from systematic_trading.research import broadtrend as b


def main():
    rows=s.read(s.OUT/'results.json');detail=json.loads(gzip.decompress((s.OUT/'detail.json.gz').read_bytes()))
    paths=json.loads(gzip.decompress((s.OUT/'paths.json.gz').read_bytes()));attrs=s.read(s.OUT/'attribution.json');diag=s.read(s.OUT/'diagnostics.json')
    names={'fr25':'100% FR25','blend':'70% FR25 / 30% BroadTrend','broadtrend':'100% BroadTrend','blend_dynamic':'70/30 · dynamic timing control'}
    colors={'fr25':'#4569a2','blend':'#158179','broadtrend':'#bd7b35'}
    dates=np.array(paths['days'],dtype='datetime64[D]');fig,ax=plt.subplots(3,1,figsize=(13,9),sharex=True)
    for arm in colors:
        key=arm+'_c5d0';nav=np.array(paths[key]);ax[0].plot(dates,100*nav,label=names[arm],color=colors[arm])
        ax[1].plot(dates,100*(nav/np.maximum.accumulate(nav)-1),color=colors[arm]);ax[2].plot(dates,100*np.array(detail[key]['cash']),color=colors[arm])
    for a in ax:a.grid(alpha=.2)
    ax[0].set_ylabel('Value / initial 100');ax[0].legend();ax[1].set_ylabel('Drawdown %');ax[2].set_ylabel('Cash %')
    fig.suptitle('Matched FR25 / BroadTrend comparison · USD net of 5 bp per side\n31 Jan 2024 cash anchor → 12 Oct 2026 · monthly capital, daily BroadTrend signals')
    fig.tight_layout();fig.savefig(s.OUT/'portfolio.png',dpi=140);plt.close(fig)
    parent_data=json.loads(gzip.decompress((s.parent.OUT/'report-data.json.gz').read_bytes()))
    charts={}
    for key,c in parent_data['charts'].items():
        if not key.endswith('_late'):continue
        n=sum(d<=paths['days'][-1] for d in c['days']);copy={k:v[:n] if isinstance(v,list) and len(v)==len(c['days']) else v for k,v in c.items()}
        copy['fills']=[f for f in c['fills'] if f['day']<=paths['days'][-1]]
        copy['trades']=[dict(t,exit_date=None,exit_price=None,net_return=None,exit_reason=None) if t['exit_date'] and t['exit_date']>paths['days'][-1] else t for t in c['trades'] if t['entry_date']<=paths['days'][-1]]
        charts[key]=copy
    original=s.parent.OUT
    try:
        s.parent.OUT=s.OUT
        for sym,arm in [('TLT','broadtrend'),('LQD','blend')]:chart(charts[sym+'_late'],sym+'_late',[f for f in detail[arm+'_c5d0']['fills'] if f['symbol']==sym])
    finally:s.parent.OUT=original
    columns=[('arm','Portfolio',lambda a:names[a]),('cumulative','Net return',pct),('cagr','CAGR',pct),('sharpe','Sharpe',num),('volatility','Volatility',pct),('max_drawdown','Max drawdown',pct),('calmar','Calmar',num)]
    primary=[r for r in rows if r['cost_bp']==5 and r['delay']==0 and r['arm']!='blend_dynamic']
    body='<h1>BroadTrend · Full-Pool ETF Trend</h1><p class="subtitle">Version 1 · 29 October 2026 · app-owned monitoring · 51 ETF sleeves</p>'
    body+='<div class="verdict"><b>BroadTrend is a useful monitored research strategy; the 70/30 blend is not an established improvement over FR25.</b> The blend lowers volatility and drawdown, but sacrifices 4.23 percentage points of annual return without improving Sharpe in the primary test. Keep the existing funded allocation while gathering prospective evidence.</div>'
    body+='<p><a href="http://127.0.0.1:8000/api/v1/strategies/broadtrend_full_pool_v1/report">Open the app’s BroadTrend strategy report</a> · <a href="../../docs/broadtrend-strategy-v1.md">Versioned strategy specification</a> · <a href="../trend-sleeve-synthesis-20261029-v1/index.html">Prior single-ETF synthesis and training lineage</a></p>'
    status=s.read(s.OUT/'monitoring-verification.json') if (s.OUT/'monitoring-verification.json').exists() else {}
    if not status.get('served_report_verified'):
        body+='<div class="verdict"><b>Monitoring registration is saved; served publication is pending.</b> The app’s full verified refresh requires10GB available memory; the current machine has about8GB. The resource check remains enforced. The app shows Monitored / Catching up. <a href="strategy-report-preview.html">Open the verified app-calculator preview</a> (snapshot through27October, not the recurring monitor).</div>'
    else:
        body+='<div class="verdict"><b>Monitoring is active and the normal app report is published.</b> Verified on 29 October after the app’s successful refresh. All 51 ETF states, simulated holdings, daily NAV, benchmarks and next-session intents are available through 27 October. The catalog still shows Catching up because USO lacks the expected 28 October observation. The funded allocation remains 100% FR25.</div>'
    body+='<h2>Matched 70/30 test</h2><p>First funded open: 1 February 2024; last mark: 12 October 2026. All three accounts begin with the same cash at the 31 January close. USD, fractional adjusted units, zero cash interest, 5 bp per traded side, next-session-open execution. Sharpe uses a zero reference rate. Maximum drawdown is a positive loss magnitude.</p>'+table(primary,columns)+'<img class="figure" src="portfolio.png" alt="Portfolio NAV, drawdown and cash comparison"/>'
    body+='<p>BroadTrend and FR25 daily returns have correlation <b>0.677</b>. The 70/30 allocation reduces annual volatility by 19.8%, but FR25 still contributes approximately 86.5% of covariance risk. Average invested capital falls from 97.9% to 84.1%; some apparent diversification is simply more cash. Effective invested breadth rises from 4.97 to 7.03, much less than the average 28.6 ETF names held.</p>'
    body+='<p>The paired 21-session block bootstrap gives a descriptive 95% interval of <b>−0.159 to +0.144</b> for the blend’s Sharpe difference, and <b>−7.47 to −1.35 percentage points</b> for its CAGR difference. These intervals do not correct for repeated strategy selection, and are not proof of future underperformance or statistical alpha.</p>'
    annual=[dict(arm=r['arm'],**r['yearly']) for r in primary]
    body+='<h3>Chronological check</h3>'+table(annual,[columns[0],('2024','Feb–Dec 2024',pct),('2025','2025',pct),('2026','2026 through Oct 12',pct)])
    body+='<p>The blend gives up return in every displayed calendar block. Comparable FR25 targets are unavailable for the earlier development era; this is not multi-cycle blend validation. The earlier separately fitted full-pool control (49 risky ETFs, Jan 2021–Dec 2022) returned −1.13%, Sharpe −0.049 and drawdown 11.04%.</p>'
    body+='<details><summary>Cost, delay and dynamic timing checks</summary><p>Primary monthly 70/30 fails the predeclared Sharpe/CAGR/drawdown guard in all six friction settings. Dynamic timing also passes 0/6. The dynamic control adopts the latest full theoretical ETF/cash target when its L1 distance from the last adopted target reaches 10%, or monthly. It never compares against drifted holdings. This changes FR25 target adoption timing as well as capital timing.</p>'+table(rows,[('cost_bp','bp / side',str),('delay','Extra sessions',str),*columns])
    body+=table([r for r in rows if r['cost_bp']==5 and r['delay']==0],[columns[0],('cost_bp_annual','Cost bp/year',lambda x:f'{x:.2f}'),('turnover_annual','Gross notional/year',lambda x:f'{x:.2f}×'),('allocations','Capital resets',str),('fills','External ETF fills',str)])+'</details>'
    body+='<h2>The strategy we are monitoring</h2><p>Every supported risky ETF receives 1/51 of capital at the monthly reset. Its frozen per-ETF trend policy trades daily, with cash retained within that sleeve after a sale. There is no ranking, top-N filter, volatility weighting, daily reinvestment of other sleeves’ cash, Bayesian refit or trained reviewer in this version. Volume is displayed for diagnosis but does not enter the selected signal. The current full-pool version uses models fitted through 30 December 2022.</p>'
    body+=b.diagram()[0]['svg']
    body+='<p>The production definition is <code>broadtrend_full_pool_v1</code>; model pack <code>broadtrend-models-1.0.0</code>, SHA-256 <code>'+b.PACK_SHA256+'</code>. Shadow states begin at the 30 December 2022 close. The funded history deliberately retains the tested 31 January 2024 anchor. That date is a comparison convention, not an economic need for a rank warmup. Starting capital earlier would be new evidence.</p>'
    body+='<details><summary>Full mathematical definition: filtering, fitting and daily trading</summary>'
    equations=s.read(s.parent.SYNTH/'equations.json')
    for e in equations:body+='<h3>'+html.escape(e['title'])+'</h3>'+eq(e['formula'])+'<p>'+html.escape(e['explanation'])+'</p>'
    body+='</details><h3>Portfolio capital and net orders</h3>'
    formulas=[(r'B_{i,m}^{+}=V_m^{+}/51,\qquad V_t=\sum_i(c_{i,t}+q_{i,t}C_{i,t})','At each allocation open, equal capital after fees; between resets cash and shares drift within each sleeve.'),
        (r'V_m^{+}=V_m^{-}-f\sum_i\left|\frac{1}{51}a_{i,m}V_m^{+}-q_{i,m}^{-}O_{i,m}\right|','a is the delayed long/cash state known before execution. Solve the scalar post-fee capital equation, then hold active budgets in shares and inactive budgets in cash.'),
        (r'q_i^{+}=q_i^{-}+c_i^{-}/[O_i(1+f)],\quad c_i^{+}=0\quad\mathrm{(buy)}','Outside allocation dates, a buy spends only the ETF sleeve cash. A sell releases q O (1−f) into that same sleeve; unchanged positions keep their quantities.'),
        (r'\Delta_s=\sum_{k\in\{F,B\}}\Delta_{k,s},\quad\mathrm{fee}=f\sum_s|\Delta_s|,\quad (V_F,V_B)=(0.7,0.3)V^{+}','For the blend, net same-ETF orders across both strategy sleeves before charging fees. At monthly resets set strategy capital70/30; between resets retain each strategy’s actual cash/shares. No weighted-average terminal return or implicit daily70/30 rebalance.'),
        (r'd_t=\|\widetilde w_t-\widetilde w_{\mathrm{last\ adopted}}\|_1,\qquad\mathrm{trigger}=\mathrm{monthend}\ \mathrm{or}\ d_t\geq0.10','Separate dynamic control only. The vector contains all ETF exposures and cash. One immutable pending instruction at a time; orders execute after the declared delay.')]
    for formula,note in formulas:body+=eq(formula)+'<p>'+html.escape(note)+'</p>'
    body+='<h2>What this version cannot establish</h2><ul><li><b>Alpha:</b> positive returns and Sharpe can reflect common equity/gold trends and cash exposure. The tested full pool beat the rank selectors on primary Sharpe; it is not a proven optimum over all portfolios.</li><li><b>True regimes:</b> the model has two Kalman slope estimates and one fast HMM, not two or three interacting economic regime HMMs. Its probabilities are scores for serially dependent derived observations, not calibrated probabilities of future profits.</li><li><b>Adaptation:</b> slopes and state beliefs update daily, but noise, volatility scale, transitions and trade thresholds stay frozen. Large losses or regime shifts do not refit this version. A future adaptation would be separately versioned.</li><li><b>Protection:</b> the stop is tested against a completed close and sold at a later open. Gaps and intraday selloffs can exceed it. Rearming and confirmation can miss rebounds; range and down-market false starts remain.</li><li><b>Fitting:</b> inherited thresholds were not jointly retuned with the final symmetric HMM. Fixed smoothing bounds impose timescales; repeated use of the same development data invites selection bias.</li><li><b>Data and execution:</b> audited reconstructed histories do not certify historical dissemination or historical pool membership. Adjusted fractional USD units, zero cash interest and flat fees omit taxes, spreads, impact and actual share/split handling. BroadTrend’s daily-sleeve execution contract is not enabled for the broker.</li></ul>'
    body+='<h2>Weakest ETFs: inspect TLT and LQD</h2><p><b>TLT</b> is BroadTrend’s worst contributor on the matched window (−0.418 percentage points). <b>LQD</b> is the combined70/30 book’s worst contributor (−1.092 points), largely inherited from FR25. TLT contributes another −1.009 points to the blend. These are actual net dollar P&amp;L divided by initial portfolio capital, not averages of individual ETF returns.</p><p>Default inspector: TLT. Choose any of the51 ETFs, hover for precise OHLC and dates, or click two endpoints to zoom. The HMM and protection lines belong to BroadTrend’s continuing shadow account; orange rings and the actual-fill table belong to the selected funded book. A FR25 fill need not follow the BroadTrend state.</p>'
    body+='<div class="controls"><select id="era"><option value="late">Matched later window</option></select><select id="etf"></select><select id="book"><option value="broadtrend">BroadTrend actual fills</option><option value="blend">70/30 actual net fills</option></select><input id="from" type="date"><input id="to" type="date"><button id="full">Full interval</button><button id="weakest">Worst BroadTrend: TLT</button><button id="lqd">Worst blend: LQD</button></div><p id="chartmetrics"></p><div id="readout">Hover over a session; click two dates to zoom.</div><svg id="chart" viewBox="0 0 1200 950" aria-label="ETF price volume states stops fills and NAV"></svg><details><summary>Frozen parameters for this ETF</summary><pre id="parameters"></pre></details><details><summary>Shadow trades</summary><table><thead><tr><th>Buy</th><th>Sell</th><th>Entry</th><th>Exit</th><th>Net return</th><th>Exit reason</th><th>Initial risk</th></tr></thead><tbody id="trades"></tbody></table></details><details><summary>Actual portfolio fills</summary><table><thead><tr><th>Date</th><th>Side</th><th>Reason</th><th>Price</th><th>Notional / initial capital</th><th>Fee / initial capital</th></tr></thead><tbody id="actualfills"></tbody></table></details>'
    body+='<details><summary>Static chart exports</summary><img class="figure" src="TLT_late.png" alt="TLT BroadTrend inspection"><img class="figure" src="LQD_late.png" alt="LQD inspection with actual blended fills"></details>'
    body+='<h2>Monitoring and verification</h2><p>Durable monitoring membership revision6 was registered through the app’s normal lifecycle service. Daily refresh uses the latest published, hash-verified full histories and recomputes causal states; it is not a static research card. The model pack remains frozen. Full-pool calculations stop at the latest common complete session and disclose lagging symbols. At initial verification that was27October because USO lacked28October.</p><p>The existing SOTA and capital allocation revision7 were preserved. Monitoring supplies reports, daily NAV, decisions, held quantities and next-session exposure intents; it does not authorize broker orders or allocation.</p><p>Validation: exact reproduction of all51 frozen ETF paths and their full-pool portfolio; all24blend/friction cases reconcile against an independent cash/share ledger; FR25 and BroadTrend standalone controls match earlier evidence; prefix-causality, fee-netting, month-end targets, model tampering and execution-boundary tests pass. Native Windows LEAN checks the exported accounting fixtures independently, with its narrower scope stated in the receipt.</p><p>Sources: <a href="protocol.json">pre-evaluation protocol</a>, <a href="results.json">all results</a>, <a href="diagnostics.json">diagnostics</a>, <a href="native-checks.json">native accounting receipts</a>, <a href="validation.json">reconciliation</a>, <a href="monitoring-verification.json">served monitoring verification</a>. Historical calendar exceptions follow <a href="https://www.isda.org/a/UViDE/equityderivativesmpissues.pdf">ISDA exchange closing records</a> and <a href="https://www.finra.org/sites/default/files/NoticeDocument/p004328.pdf">NASD’s1998MLK notice</a>.</p>'
    data=dict(charts=charts,models={s+'_late':m for s,m in b.model_pack()['models'].items()},weakest={'late':'TLT'},portfolio=detail)
    s.gzwrite(s.OUT/'report-data.json.gz',data)
    js=(s.parent.OUT/'controls.js').read_text(encoding='utf8').split('function portfolio(){')[0]
    js+='''\nconst originalRender=render;render=function(){originalRender();if(indices.length<2){el('actualfills').innerHTML='';return}let q=c(),z=DATA.portfolio[el('book').value+'_c5d0'];let fills=z.fills.filter(f=>f.symbol===el('etf').value&&f.date>=el('from').value&&f.date<=el('to').value);el('actualfills').innerHTML=fills.map(f=>`<tr><td>${f.date}</td><td>${f.side}</td><td>${f.reason}</td><td>${f.price.toFixed(2)}</td><td>${pct(f.notional)}</td><td>${pct(f.fee)}</td></tr>`).join('');let prices=indices.flatMap(i=>[q.high[i],q.low[i],q.stop[i]]).filter(v=>v!=null),lo=Math.min(...prices),hi=Math.max(...prices);for(let f of fills){let j=indices.findIndex(i=>q.days[i]===f.date);if(j<0)continue;let x=75+1090*j/(indices.length-1),y=280-230*(f.price-lo)/(hi-lo||1);el('chart').innerHTML+=`<circle cx="${x}" cy="${y}" r="4.5" fill="none" stroke="#d78020" stroke-width="1.5"/>`}};el('book').addEventListener('change',render);el('lqd').addEventListener('click',()=>{el('etf').value='LQD';el('book').value='blend';choose()});render();'''
    (s.OUT/'controls.js').write_text(js,encoding='utf8')
    encoded=base64.b64encode((s.OUT/'report-data.json.gz').read_bytes()).decode()
    css='body{font:16px/1.55 system-ui;color:#19364b;background:#f6f8fa;max-width:1250px;margin:auto;padding:28px}h1{font-size:38px}h2{margin-top:2em}p{max-width:1120px}.subtitle{color:#5d7182}.verdict{padding:22px;background:#e7f4ef;border-left:5px solid #158179}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:9px;border-bottom:1px solid #d5e1e8;text-align:right}th:first-child,td:first-child{text-align:left}.scroll{overflow:auto}.figure{width:100%}details{background:white;padding:15px;margin:18px 0;border:1px solid #d6e2e8}summary{cursor:pointer;font-weight:600}pre{white-space:pre-wrap;font-size:12px}.equation{overflow:auto;background:white;padding:8px}.equation svg{max-width:none;width:auto;height:52px}.controls{display:flex;gap:8px;flex-wrap:wrap}button,select,input{font:inherit;padding:7px}#chart{width:100%;background:white}#readout{position:sticky;top:0;background:#edf4f7;padding:12px;z-index:1}code{word-break:break-all}li{margin:10px 0}'
    loader="const DATA=JSON.parse(await new Response(new Blob([Uint8Array.from(atob('"+encoded+"'),c=>c.charCodeAt(0))]).stream().pipeThrough(new DecompressionStream('gzip'))).text());\n"
    (s.OUT/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BroadTrend and FR2570/30</title><style>'+css+'</style><body>'+body+'<script type="module">'+loader+js+'</script></body></html>',encoding='utf8')
    print('Built',s.OUT/'index.html',len(charts),'ETF inspectors',flush=True)


if __name__=='__main__':main()
